  <div class="sheets" role="tablist" aria-label="Feuilles du classeur">${s.sheets.map(a=>`<button role="tab" class="sheet-tab ${a.name===i.name?"on":""}" aria-selected="${a.name===i.name}" data-xs="${esc(a.name)}"><b>${esc(a.name)}</b><span>${esc(a.type)}</span></button>`).join("")}</div>
